import{_ as d,V as c,W as a,Z as e,$ as t,a0 as i,Y as r,F as n,a1 as l}from"./framework-b1bd8911.js";const s={},u=r('<h1 id="audio-plugin-音频处理" tabindex="-1"><a class="header-anchor" href="#audio-plugin-音频处理" aria-hidden="true">#</a> audio-plugin 音频处理</h1><blockquote><p>audio-plugin 是 QuickMedia 多媒体工具箱中负责音频处理的插件，目前提供的核心能力是<strong>音频转码</strong>：底层封装 <code>ffmpeg</code> 命令行调用，上层对外暴露链式的 <code>AudioWrapper</code> 使用接口，几行代码就能完成本地文件、网络音频、输入流之间的格式转换（如微信语音常见的 <code>amr</code> 转 h5 可直接播放的 <code>mp3</code>）。</p></blockquote><h2 id="能力清单" tabindex="-1"><a class="header-anchor" href="#能力清单" aria-hidden="true">#</a> 能力清单</h2><ul><li><strong>音频转码</strong>：基于 <code>ffmpeg</code> 实现任意常见音频格式之间的转换（<code>amr</code>/<code>mp3</code>/<code>wav</code>/<code>ogg</code>/<code>m4a</code>...）</li><li><strong>三种输入源</strong>：本地文件路径（绝对/相对路径）、网络 URL、<code>InputStream</code> 输入流</li><li><strong>两种输出方式</strong>：转码后保存为文件（<code>asFile</code>），或者直接拿到输出的 <code>InputStream</code>（<code>asStream</code>）</li><li><strong>命令行参数可扩展</strong>：通过 <code>addOption</code> 可以追加任意 <code>ffmpeg</code> 参数，默认自带 <code>-y</code>（覆盖写）、<code>write_xing 0</code>（解决 mac/ios 音频时长显示不对）、<code>loglevel quiet</code>（不输出日志）三个兜底配置</li><li><strong>临时文件管理</strong>：网络资源、输入流会先落到临时目录再转码，临时目录可通过系统属性 <code>quick.media.tmp.path</code> 自定义</li></ul><h2 id="相关文章" tabindex="-1"><a class="header-anchor" href="#相关文章" aria-hidden="true">#</a> 相关文章</h2>',5);function h(g,m){const o=n("RouterLink");return c(),a("div",null,[u,e("ul",null,[e("li",null,[t(o,{to:"/git/quick-media/audio/01.%E5%9F%BA%E4%BA%8EFFMPEG%E5%AE%9E%E7%8E%B0%E9%9F%B3%E9%A2%91%E8%BD%AC%E7%A0%81.html"},{default:i(()=>[l("基于FFMPEG实现音频转码")]),_:1})])])])}const _=d(s,[["render",h],["__file","index.html.vue"]]);export{_ as default};
